# Own-wording feats of Valda's Spire of Secrets (2014 rules), part B.
ALSO = []
NH = "Near-Human, 1st level only"
ANY = ["STR", "DEX", "CON", "INT", "WIS", "CHA"]
CC = "Character creation only"
DV = [["Darkvision", 60, ""]]
SPELLSTAT = " Choose Intelligence, Wisdom or Charisma as the spellcasting ability when you take the feat."
FEATS = {
 "Marksman's Luck": {"d": "Once per turn, flip one ranged weapon damage die (not a d4) to its opposite face.",
   "full": "Once per turn, when you roll damage with a ranged weapon, you can flip one damage die and use the number on its underside instead. This does not work on d4s. The opposite faces of a fair die add up to one more than its highest number."},
 "Master Thrower": {"d": "Bonus action thrown attack, free weapon draws, and doubled thrown ranges.", "pre": "Dexterity 13", "asi": ["DEX"],
   "full": "When you take the Attack action, you can use a bonus action to make a ranged attack with a thrown weapon. You do not add your ability modifier to its damage unless the modifier is negative. When you make a ranged weapon attack you can draw the weapon as part of it, and you can draw any number of weapons this way each round. Short and long ranges of your thrown weapons double."},
 "Mul": {"d": "Human-dwarf blood: Darkvision 60 ft, heavy armor without penalties, and 1 extra hit point per level.", "pre": NH, "asi": ANY,
   "full": "**Darkvision.** You see in dim light within 60 feet as if bright, and in darkness as if dim. You see only shades of gray in darkness.\n**Armor Acclimation.** Heavy armor never lowers your Speed and never gives you Disadvantage on Dexterity (Stealth) checks.\n**Dwarven Toughness.** Your hit point maximum rises by 1, and by 1 more each time you gain a level.",
   "fx": {"senses": DV, "notes": [["Note", "Dwarven Toughness: +1 hit point maximum, and +1 per level"]]}},
 "Ogre-Blooded": {"d": "Darkvision 60 ft, Athletics proficiency with a floor on your checks, and Powerful Build.", "pre": NH, "asi": ANY,
   "full": "**Darkvision.** You see in dim light within 60 feet as if bright, and in darkness as if dim. You see only shades of gray in darkness.\n**Monstrous Strength.** You gain proficiency in Athletics. On a Strength (Athletics) check you can treat the d20 result as 10 or as your level plus your Strength modifier, whichever is higher.\n**Powerful Build.** You count as one size larger for carrying capacity and for the weight you can push, drag or lift.",
   "fx": {"senses": DV, "skills": ["Athletics"]}},
 "Owlbearman": {"d": "Beak for 1d6 piercing unarmed strikes, and grapple creatures two sizes larger.", "pre": NH, "asi": ANY,
   "full": "**Beak.** Your hooked beak makes unarmed strikes that deal 1d6 + your Strength modifier piercing damage.\n**Owlbear Wrestling.** You can grapple creatures up to two sizes larger than you. You have Advantage on grapple checks on your turn against creatures at least one size smaller than you."},
 "Porterling": {"d": "Escape grapples and bindings with Advantage, add d8 feet to jumps, and squeeze through tight spaces.", "pre": NH, "asi": ANY,
   "full": "**Flexible.** You have Advantage on checks to escape a grapple or slip out of bindings.\n**Springheel Leap.** When you make a long or high jump, roll a d8 and add it to the feet you cover, even from a standing jump. The extra distance costs movement as usual.\n**Squeeze.** You take no penalty for squeezing through a space made for a creature one size smaller than you."},
 "Precognitive": {"d": "Three times per Long Rest, roll a d20 at turn start and use it for your next attack, check or save this turn.", "pre": "Wisdom 13", "asi": ["WIS"],
   "full": "You sense events an instant before they happen. When your turn begins, you can roll a d20 and note the number. The next attack roll, ability check or saving throw you make before the end of the turn uses this number in place of the roll. You can do this three times, and a Long Rest restores all uses.",
   "lu": {"n": "Precognitive", "max": 3, "reset": "long", "tag": "Start of turn"}},
 "Prophesied": {"d": "Your fate is foretold: while the prophecy plays out, the GM decides your rolls.", "pre": CC,
   "full": "A fortune-teller or a great prophecy has fixed one moment of your future. Choose the prophecy and share it with the GM. When it comes true, you do not roll attack rolls, ability checks or saving throws during the prophesied events. The GM decides those results for you."},
 "Proto-Man": {"d": "Advantage against fear and a free Hit Die on each Short Rest, once per Long Rest.", "pre": NH, "asi": ANY,
   "full": "**Brave.** You have Advantage on saves to avoid or end the frightened condition on you.\n**Primal Recovery.** When you take a Short Rest you can regain 1 Hit Die and spend it right away. A Long Rest restores this use.",
   "lu": {"n": "Primal Recovery", "max": 1, "reset": "long", "tag": "Short Rest"}},
 "Psionic": {"d": "Read emotions, invisible Mage Hand, then Unseen Servant and Levitate once each per Long Rest.", "pre": NH, "asi": ANY,
   "full": "**Empathy.** As an action, probe the surface emotions of a creature within 30 feet that you see and that has Intelligence 3 or higher. You learn its emotional state and, at the GM's discretion, one of its Bonds.\n**Psionics.** You know the Mage Hand cantrip, and the hand is invisible when you cast it this way. At level 3 you can cast Unseen Servant once with this trait, and at level 5 Levitate once. A Long Rest restores each. You can also cast them with slots of the right level." + SPELLSTAT, "act": "action"},
 "Reptiloid": {"d": "Replace an attack with a 30 ft acid spit, 1d10 acid scaling with level, Proficiency Bonus uses per Long Rest.", "pre": NH, "asi": ANY,
   "full": "**Acid Spit.** When you take the Attack action you can replace one attack with a lob of acid. It is a ranged attack with range 30 feet, you are proficient with it, and you add your Dexterity modifier to its attack and damage rolls. A hit deals 1d10 acid damage, rising to 2d10 at level 5, 3d10 at level 11 and 4d10 at level 17. You can use it a number of times equal to your Proficiency Bonus, and a Long Rest restores all uses.",
   "lu": {"n": "Acid Spit", "max": "pb", "reset": "long", "tag": "Ranged 30 ft, 1d10 acid"}},
 "Roguean": {"d": "Darkvision 60 ft, Cold resistance, and tolerance of -100 to 300 degrees Fahrenheit.", "pre": NH, "asi": ANY,
   "full": "**Darkvision.** You see in dim light within 60 feet as if bright, and in darkness as if dim. You see only shades of gray in darkness.\n**Cold Resistance.** You have Resistance to Cold damage.\n**Extremophile.** You can endure temperatures from -100 to 300 degrees Fahrenheit.",
   "fx": {"res": ["Cold"], "senses": DV}},
 "Secret": {"d": "Pick one falsehood about yourself. You never need a Deception check to maintain it.", "pre": CC,
   "full": "Choose one falsehood about yourself and practice it until you can recite it perfectly. It can be one lie or a whole false history. You never need a Deception check to maintain this falsehood."},
 "Showman": {"d": "Performance proficiency or expertise, and a bonus equal to your audience size (up to Charisma modifier) three times per Long Rest.", "asi": ["CHA"],
   "full": "You gain proficiency in Performance. If you already have it, you add double your Proficiency Bonus to it instead.\nWhen a non-hostile audience watches you fight, once per turn you can add a bonus to an ability check or attack roll equal to the number of onlookers, up to your Charisma modifier. You can do this three times, and a Long Rest restores all uses.",
   "fx": {"skills": ["Performance"]}, "lu": {"n": "Showman", "max": 3, "reset": "long", "tag": "Audience bonus"}},
 "Soul Twin": {"d": "Two bodies, one soul: shared actions, separate hit points, spells and effects mostly hit both.", "pre": CC,
   "full": "You and your twin are identical twins who share one soul, a single character with two bodies you control.\n**Actions.** The twins share one action, bonus action and reaction per turn. If you take Dash, Disengage, Dodge, Help, Hide, Ready or Search, both twins gain the benefit.\n**Attacks.** When one twin attacks with the Attack action, the other can attack as a bonus action, adding no ability modifier to damage unless it is negative. With several attacks you can split them between the twins.\n**Hit Points.** Each twin has its own hit points. At 1st level each has the hit points of a normal character of your class. At each level each twin gains your Constitution modifier plus half the Hit Die (rounded up), or 2, 3, 3 or 4 for d6, d8, d10 or d12 average. You spend Hit Dice separately for each twin.\n**Spellcasting.** You can concentrate on one spell at a time, and one twin concentrating is enough. Either twin can supply components, and a spell can originate from either twin.\n**Magical Effects.** A spell or ability that affects one twin affects both, unless it deals with hit points or the twins are over 100 feet apart. Then it affects each separately.\n**Conditions.** A condition affects only the twin it was put on.\n**Death.** When one twin starts making death saves, the other is incapacitated with halved Speed. If one twin dies, the other dies 24 hours later unless the partner returns to life.\n**Empathic Link.** On the same plane, the twins sense each other's emotions and know when the other takes damage.\nAs a rule of thumb, effects that heal, harm or grab affect one twin, and effects that charm, curse, enchant or protect affect both. The GM rules unclear cases. This is an advanced option, not for new players or those who control many creatures."},
 "Spellblade": {"d": "One martial melee weapon, elemental damage swaps on melee hits, two blade cantrips, and Shield once per Long Rest.",
   "full": "You gain proficiency with one martial melee weapon. When you deal bludgeoning, piercing or slashing damage with a melee weapon, you can change it to acid, cold, fire or lightning damage. You learn two cantrips from Arc Blade, Burning Blade, Caustic Blade and Frigid Blade, using Intelligence. You can cast Shield once with no slot, and a Long Rest restores that.",
   "lu": {"n": "Spellblade: Shield", "max": 1, "reset": "long", "tag": "No slot"}},
 "Stheno": {"d": "Replace an attack with a 60 ft gaze: Constitution save or incapacitated with Speed 0, Proficiency Bonus uses.", "pre": NH, "asi": ANY,
   "full": "**Immobilizing Gaze.** When you take the Attack action you can replace one attack with this gaze. Pick a creature within 60 feet that can see you. It makes a Constitution save (DC 8 + your Constitution modifier + your Proficiency Bonus). A creature immune to being restrained succeeds automatically. On a failed save it is incapacitated and its Speed is 0 until the start of your next turn. You can use it a number of times equal to your Proficiency Bonus, and a Long Rest restores all uses.",
   "lu": {"n": "Immobilizing Gaze", "max": "pb", "reset": "long", "tag": "Con save"}},
 "Stoneborn": {"d": "+1 AC, Advantage against being knocked prone or moved, and sense gems and metals in stone.", "pre": NH, "asi": ANY,
   "full": "**Stony Skin.** You have a +1 bonus to AC.\n**Sure-Footed.** You have Advantage on ability checks and saves to resist being knocked prone or moved against your will.\n**Oresight.** With a hand on natural stone and an action to focus, you feel natural gems or metals within 100 feet.",
   "fx": {"notes": [["Note", "Stony Skin: +1 bonus to AC"]]}, "act": "action"},
 "Tauran": {"d": "Horns for 1d6 piercing unarmed strikes, always know north, and +10 ft Speed on straight-line turns.", "pre": NH, "asi": ANY,
   "full": "**Horns.** Your horns make unarmed strikes that deal 1d6 + your Strength modifier piercing damage.\n**Labyrinthine Recall.** You always know which way is north and have Advantage on Wisdom (Survival) checks to navigate or track.\n**Rush.** On any turn in which you move only in a straight line, your Speed rises by 10 feet."},
 "Traveler": {"d": "Disadvantage on History checks about this land, and you can share simple ideas by gesture.", "pre": CC,
   "full": "You come from a place so far away that you may never return, perhaps another plane, another time or the far side of the ocean. You know little of this land, its history and its people, and they know little of you. You have Disadvantage on Intelligence (History) checks about the history or customs of this land. You can communicate simple ideas through gestures to any creature that understands at least one language."},
 "Troll-Blooded": {"d": "Regain 1 hit point per minute while at one quarter of your hit points or less (not at 0).", "pre": NH, "asi": ANY,
   "full": "**Troll Regeneration.** You regain 1 hit point each minute while you have no more than one quarter of your hit points (rounded down). You cannot use this trait at 0 hit points."},
 "Two-Headed": {"d": "Advantage against blinded, charmed, deafened and frightened, and you stay conscious during a Long Rest.", "pre": NH, "asi": ANY,
   "full": "**Two-Heads.** You have Advantage on saves to avoid or end the blinded, charmed, deafened and frightened conditions on you.\n**Wakeful.** One head is always awake, so you remain conscious during a Long Rest.",
   "fx": {"notes": [["Note", "Two-Heads: Advantage on saves against being blinded, charmed, deafened or frightened"]]}},
 "Undead": {"d": "No need to eat, drink, sleep or breathe. Advantage on poison saves and Poison resistance.", "pre": CC,
   "full": "You are caught between death and life, a revenant, a lich or something unique born of a curse or accident. You do not need to eat, drink, sleep or breathe. You still spend 8 hours in light activity, such as keeping watch, to gain the benefit of a Long Rest. You have Advantage on saves against poison and Resistance to Poison damage. Your type is Humanoid, but spells and effects that target undead also affect you.",
   "fx": {"res": ["Poison"], "notes": [["Note", "Undead: Advantage on saves against poison. You do not need to eat, drink, sleep or breathe"]]}},
 "Upcaster": {"d": "Combine two slots of one level into a slot one level higher and cast a known or prepared spell with it.", "pre": "Spellcasting",
   "full": "You can spend two spell slots of the same level to create one slot a level higher and immediately cast a spell you know or have prepared with it."},
 "Upper Limb Disability": {"d": "Pick a Disadvantage for heavy or for finesse and ranged weapons, and gain Advantage on readied weapon attacks.", "pre": CC,
   "full": "Injury, illness or birth means you cannot use your arms as others do. The cause might be paralysis, an amputated arm or hand, poor manual dexterity, arthritis or chronic pain. Even without an arm or hand you can fight with two weapons or a weapon and shield through prosthetics or a mechanical or magical aid.\nChoose one trait that fits your disability: Disadvantage on attack rolls with heavy weapons and on Strength checks that need your hands, or Disadvantage on attack rolls with finesse and ranged weapons and on Dexterity checks that need your hands.\nYou also have Advantage on weapon attacks you prepare with the Ready action.\nIf your limb is ever restored, such as by Regenerate, you lose this feat. Talk with your GM about whether that fits your character."},
 "Windswept": {"d": "Lightning resistance, Message, then Feather Fall and Gust of Wind once each per Long Rest.", "pre": NH, "asi": ANY,
   "full": "**Lightning Resistance.** You have Resistance to Lightning damage.\n**Zephyr Magic.** You know the Message cantrip. At level 3 you can cast Feather Fall once with this trait, and at level 5 Gust of Wind once, with no material component. A Long Rest restores each. You can also cast them with slots of the right level." + SPELLSTAT,
   "fx": {"res": ["Lightning"]}},
 "Winged": {"d": "Flying Speed equal to your walking Speed, unusable in medium or heavy armor.", "pre": NH, "asi": ANY,
   "full": "**Flight.** Your wings give you a flying Speed equal to your walking Speed. You cannot use it while wearing medium or heavy armor.",
   "fx": {"mv": {"fly": "speed"}}},
}
